  "heavy scenario loaded": "\u049a\u0430\u0440\u049b\u044b\u043d\u0434\u044b \u049b\u043e\u0437\u0493\u0430\u043b\u044b\u0441 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439\u0456 \u0436\u04af\u043a\u0442\u0435\u043b\u0434\u0456",
  "overload scenario loaded": "\u0422\u04e9\u0442\u0435\u043d\u0448\u0435 \u0436\u04af\u043a\u0442\u0435\u043c\u0435 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439\u0456 \u0436\u04af\u043a\u0442\u0435\u043b\u0434\u0456",
  "Fuel critical; priority escalated": "\u0416\u0430\u043d\u0430\u0440\u043c\u0430\u0439 \u049b\u043e\u0440\u044b \u0441\u044b\u043d\u0438 \u0434\u0435\u04a3\u0433\u0435\u0439\u0434\u0435; \u0431\u0430\u0441\u044b\u043c\u0434\u044b\u049b \u043a\u04e9\u0442\u0435\u0440\u0456\u043b\u0434\u0456",
  "Fuel endurance exhausted before runway service": "\u04b0\u049a\u0416 \u049b\u044b\u0437\u043c\u0435\u0442\u0456\u043d\u0435 \u0434\u0435\u0439\u0456\u043d \u0436\u0430\u043d\u0430\u0440\u043c\u0430\u0439 \u0442\u0430\u0443\u0441\u044b\u043b\u0434\u044b; \u0440\u0435\u0439\u0441\u0442\u0456\u04a3 \u0431\u0430\u0493\u044b\u0442\u044b \u04e9\u0437\u0433\u0435\u0440\u0442\u0456\u043b\u0434\u0456",
