  "Runway service started: departure": "\u04b0\u049a\u0416 \u049b\u044b\u0437\u043c\u0435\u0442\u0456 \u0431\u0430\u0441\u0442\u0430\u043b\u0434\u044b: \u04b1\u0448\u0443",
  "Automatic random arrival generated": "\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0442\u044b \u0442\u04af\u0440\u0434\u0435 \u043a\u0435\u0437\u0434\u0435\u0439\u0441\u043e\u049b \u043a\u0435\u043b\u0443 \u0440\u0435\u0439\u0441\u0456 \u0436\u0430\u0441\u0430\u043b\u0434\u044b",
  "Automatic random departure generated": "\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0442\u044b \u0442\u04af\u0440\u0434\u0435 \u043a\u0435\u0437\u0434\u0435\u0439\u0441\u043e\u049b \u04b1\u0448\u0443 \u0440\u0435\u0439\u0441\u0456 \u0436\u0430\u0441\u0430\u043b\u0434\u044b",
  "Custom scenario values are out of range": "\u041f\u0430\u0439\u0434\u0430\u043b\u0430\u043d\u0443\u0448\u044b \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439\u0456\u043d\u0456\u04a3 \u043c\u04d9\u043d\u0434\u0435\u0440\u0456 \u0440\u04b1\u049b\u0441\u0430\u0442 \u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0430\u0443\u049b\u044b\u043c\u043d\u0430\u043d \u0442\u044b\u0441",
  "Automatic generation": "\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0442\u044b \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f",
